            result = 1.0 - model_loss / baseline_loss
        elif model_loss == 0.0:
            result = 1.0
        else:
            result = 0.0
        if not math.isfinite(result):
            raise FloatingPointError(
                "non-finite value encountered during d2 pinball score"
            )
    except (OverflowError, ValueError, ZeroDivisionError) as exc:
        raise FloatingPointError(
            "non-finite value encountered during d2 pinball score"
        ) from exc

    if result == 0:
        result = 0.0
    return result


